"""gw_agent.py  --  the same AskIT agent, with the tools coming from a DOOR you choose.   >>> YOU DO NOT EDIT THIS FILE <<<

Door 1 = the tools sit inside your own program (Days 5 to 9).
Door 2 = the tools are reached through the Gateway (they list themselves, you call them over the web).
The agent loop is identical: ask the model -> it asks for a tool -> run it -> give the result back -> repeat.
"""
import json
import time

from langchain_core.messages import HumanMessage, SystemMessage, ToolMessage
from langchain_core.tools import StructuredTool

import model_factory as mf

PROMPT = ("You are AskIT, the Orbit Corp IT helpdesk assistant. Use the tools to answer. Answer in at most 3 short sentences. "
          "If a tool returns an error, say so plainly; do not guess.")
MAX_STEPS = 5


def run(question, provider, specs, call_tool):
    """specs: [{"name","alias","description","schema"}].  call_tool(full_name, args) -> (python value, ms).
    The model sees the short alias (get_ticket); the Gateway needs the full name (askit-lambda___get_ticket)."""
    t0 = time.time()
    by_alias = {s["alias"]: s for s in specs}
    tools = [StructuredTool.from_function(func=lambda **kw: "", name=s["alias"], description=s["description"], args_schema=s["schema"]) for s in specs]
    model = mf.get_model(provider).bind_tools(tools)
    messages = [SystemMessage(content=PROMPT), HumanMessage(content=question)]
    steps, tin, tout, answer = [], 0, 0, ""
    for n in range(1, MAX_STEPS + 1):
        t1 = time.time()
        msg = model.invoke(messages)
        text = mf.text_of(msg)
        um = getattr(msg, "usage_metadata", None) or {}
        tin += int(um.get("input_tokens") or mf.approx_tokens("".join(mf.text_of(m) for m in messages)))
        tout += int(um.get("output_tokens") or mf.approx_tokens(text or "tool call"))
        steps.append({"kind": "model", "label": f"Model call {n}", "ms": int((time.time() - t1) * 1000), "out": text or "(asks for a tool)"})
        answer = text
        messages.append(msg)
        if not msg.tool_calls:
            break
        for c in msg.tool_calls:
            spec = by_alias.get(c["name"])
            if spec is None:
                value, ms = {"error": f"No tool called {c['name']}."}, 0
            else:
                value, ms = call_tool(spec["name"], c["args"])
            steps.append({"kind": "tool", "label": f"{spec['name'] if spec else c['name']}({', '.join(f'{k}={v}' for k, v in c['args'].items())})", "ms": ms,
                          "out": json.dumps(value)[:200]})
            messages.append(ToolMessage(content=json.dumps(value, ensure_ascii=False), tool_call_id=c["id"], name=c["name"]))
    else:
        answer = "(stopped after %d steps)" % MAX_STEPS
    return {"answer": answer, "steps": steps, "ms": int((time.time() - t0) * 1000), "tokens_in": tin, "tokens_out": tout,
            "cost_usd": mf.cost_usd(provider, tin, tout)}
